"""Calibration and discrimination metrics for confidence probes."""

import numpy as np
from sklearn.metrics import roc_auc_score


def compute_ece(probs: np.ndarray, labels: np.ndarray, n_bins: int = 15) -> float:
    """Expected Calibration Error with equal-width bins."""
    bin_edges = np.linspace(0.0, 1.0, n_bins + 1)
    ece = 0.0
    for i in range(n_bins):
        mask = (probs > bin_edges[i]) & (probs <= bin_edges[i + 1])
        if i == 0:
            mask = (probs >= bin_edges[i]) & (probs <= bin_edges[i + 1])
        count = mask.sum()
        if count == 0:
            continue
        avg_conf = probs[mask].mean()
        avg_acc = labels[mask].mean()
        ece += (count / len(probs)) * abs(avg_conf - avg_acc)
    return float(ece)


def compute_ada_ece(probs: np.ndarray, labels: np.ndarray, n_bins: int = 15) -> float:
    """Adaptive ECE with equal-count (equal-mass) bins."""
    sorted_indices = np.argsort(probs)
    sorted_probs = probs[sorted_indices]
    sorted_labels = labels[sorted_indices]

    bin_size = len(probs) // n_bins
    ada_ece = 0.0
    for i in range(n_bins):
        start = i * bin_size
        end = start + bin_size if i < n_bins - 1 else len(probs)
        bin_probs = sorted_probs[start:end]
        bin_labels = sorted_labels[start:end]
        if len(bin_probs) == 0:
            continue
        avg_conf = bin_probs.mean()
        avg_acc = bin_labels.mean()
        ada_ece += (len(bin_probs) / len(probs)) * abs(avg_conf - avg_acc)
    return float(ada_ece)


def compute_brier(probs: np.ndarray, labels: np.ndarray) -> float:
    """Brier score (mean squared error of probabilistic predictions)."""
    return float(np.mean((probs - labels) ** 2))


def compute_auroc(probs: np.ndarray, labels: np.ndarray) -> float:
    """Area under the ROC curve."""
    if len(np.unique(labels)) < 2:
        return float("nan")
    return float(roc_auc_score(labels, probs))


def compute_all_metrics(probs: np.ndarray, labels: np.ndarray) -> dict:
    """Compute all calibration and discrimination metrics."""
    return {
        "auroc": compute_auroc(probs, labels),
        "ece": compute_ece(probs, labels),
        "ada_ece": compute_ada_ece(probs, labels),
        "brier": compute_brier(probs, labels),
        "accuracy": float((probs >= 0.5).astype(int).mean() == labels.mean())
            if len(labels) == 0
            else float(((probs >= 0.5).astype(int) == labels).mean()),
        "n_test": int(len(labels)),
    }

